import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { randomUUID } from 'node:crypto';

/**
 * A journal entry on a recipe. There is no author field: only the recipe's
 * author may write entries, so ownership is checked through the recipe.
 */
@Schema({
  collection: 'journals',
  timestamps: { createdAt: 'postedAt', updatedAt: false },
  versionKey: false,
})
export class Journal {
  /** GUID string, generated by the API (not a Mongo ObjectId). */
  @Prop({ type: String, default: () => randomUUID() })
  _id: string;

  @Prop({ type: String, required: true })
  recipeId: string;

  @Prop({ type: String, required: true })
  content: string;

  /** Null until the first edit. */
  @Prop({ type: Date, default: null })
  editedAt: Date | null;

  /** Set by Mongoose timestamps. */
  postedAt: Date;
}

export const JournalSchema = SchemaFactory.createForClass(Journal);

// Serves a recipe's entries, newest first, and the per-recipe counts.
JournalSchema.index({ recipeId: 1, postedAt: -1 });
